const (
	OAuthRouteDirect        = "direct"
	OAuthRouteHosted        = "hosted"
	OAuthRoutePublic        = "public"
	OAuthRouteProtocol      = "protocol"
	OAuthRouteCompatibility = "compatibility"
)

// OAuthRouteCapability binds one registered HTTP method and Gin full path to
// its delegation policy. A path containing a Gin parameter is an exact route
// identity, never a prefix or wildcard authorization rule. Existing role,
// object ownership, and fine-grained permission guards remain mandatory.
// Hosted routes complete in a real user session through a bound action flow.
// Protocol routes retain their own authentication and accept no delegated API
// access merely because the caller holds a business scope. Compatibility
// routes are pre-existing unimplemented provider endpoints, not new features.
type OAuthRouteCapability struct {
	Method      string `json:"method"`
	Path        string `json:"path"`
	Scope       string `json:"scope"`
	Resource    string `json:"resource"`
	Mode        string `json:"mode"`
	MinRole     int    `json:"min_role"`
	Description string `json:"description"`
}

