var oauthRouteCapabilityIndex = func() map[string]OAuthRouteCapability {
	index := make(map[string]OAuthRouteCapability, len(oauthRouteCapabilities))
	for _, route := range oauthRouteCapabilities {
		key := route.Method + " " + route.Path
		if _, exists := index[key]; exists {
			panic(fmt.Sprintf("duplicate OAuth route: %s", key))
		}
		index[key] = route
	}
	return index
}()

// OAuthRouteFor returns only an exact registered method and Gin full path.
// Unknown routes deliberately have no default policy.
func OAuthRouteFor(method, fullPath string) (OAuthRouteCapability, bool) {
	route, exists := oauthRouteCapabilityIndex[method+" "+fullPath]
	return route, exists
}

// OAuthRouteCatalog returns a copy so callers cannot mutate authorization rules.
func OAuthRouteCatalog() []OAuthRouteCapability {
	return append([]OAuthRouteCapability(nil), oauthRouteCapabilities...)
}
